/**
 * The types `save/presets/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    GlobalPresetSaveRow, GlobalPresetsSaveExtract
 * depends    —
 * used by    src/save/presets/index, src/save/presets/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */

/** One Global Preset: which preset of each system it switches to. */
export interface GlobalPresetSaveRow {
  index: number
  name: string
  workshop: number | null
  cards: number | null
  bots: number | null
  modules: number | null
  guardians: number | null
}

export interface GlobalPresetsSaveExtract {
  presets: GlobalPresetSaveRow[]
  currentPreset: number | null
  /** The Global Preset assigned to each kind of battle, as stored. */
  tierPreset: number | null
  tournamentPreset: number | null
  dissonantPreset: number | null
  warnings: string[]
}
